// Validation des données d'entrée
const body = $input.first().json.body;

if (!body || !body.fileData) {
  throw new Error('fileData manquant dans la requête');
}
if (!body.periode || !/^\d{2}-\d{4}$/.test(body.periode)) {
  throw new Error('Période invalide. Format requis: MM-YYYY');
}
if (!body.gasUrl) {
  throw new Error('URL Google Apps Script manquante');
}

// Décoder le base64 en buffer
const buffer = Buffer.from(body.fileData, 'base64');

// Vérifier le header PDF
const header = buffer.slice(0, 5).toString('ascii');
const estPDF = header.startsWith('%PDF');

return [{
  json: {
    fileData: body.fileData,
    fileName: body.fileName || 'upload.pdf',
    periode: body.periode,
    gasUrl: body.gasUrl,
    pagesBase64: Array.isArray(body.pagesBase64) ? body.pagesBase64 : [],
    estPDF: estPDF,
    tailleFichier: buffer.length,
    timestamp: new Date().toISOString()
  }
}];

// Les pages ont été extraites par GAS lors du uploadPDF — aucun appel HTTP ici
const gasReponse = $input.first().json;
const fileId = gasReponse.fileId || (gasReponse.data && gasReponse.data.fileId) || null;

if (!fileId) {
  throw new Error('GAS n\'a pas retourné de fileId. Réponse : ' + JSON.stringify(gasReponse).substring(0, 200));
}

const pages = Array.isArray(gasReponse.pages) ? gasReponse.pages : [];

if (pages.length === 0) {
  const errDetail = gasReponse.extractionError || 'aucun détail — vérifiez les logs GAS Apps Script';
  throw new Error('GAS 0 pages. Erreur extraction : ' + errDetail);
}

const validationData = $("Validation des données d'entrée").item.json;
const gasUrl     = validationData.gasUrl;
const periode    = validationData.periode;
const pagesBase64 = validationData.pagesBase64 || [];

// Log des pages sans nom pour diagnostic regex
const sansNom = pages.filter(p => !p.nomPrenom);
if (sansNom.length > 0) {
  console.warn(sansNom.length + ' page(s) sans nomPrenom. debugLines :');
  sansNom.forEach(p => {
    console.warn('Page ' + p.pageIndex + ':', JSON.stringify(p.debugLines || p.texte));
  });
}

console.log('pagesBase64 reçues du navigateur :', pagesBase64.length);

return [{ json: { pages, totalPages: pages.length, fileId, gasUrl, periode, pagesBase64 } }];

// Faire correspondre chaque page avec un salarié
const extraitData = $("Extraire le texte du PDF").item.json;
const pages = extraitData.pages;
const fileId = extraitData.fileId;
const periode = extraitData.periode;
const pagesBase64 = extraitData.pagesBase64 || [];

// GAS listerSalaries retourne un tableau brut → n8n crée un item par salarié
// Il faut donc utiliser $input.all() pour reconstruire le tableau complet
const allItems = $input.all();
let salaries = [];
if (allItems.length > 0) {
  const first = allItems[0].json;
  if (Array.isArray(first?.salaries)) {
    // Objet encapsulé { salaries: [...] }
    salaries = first.salaries;
  } else if (Array.isArray(first?.data)) {
    salaries = first.data;
  } else if (first?.nomPrenom || first?.id) {
    // Tableau brut : chaque item n8n est un salarié
    salaries = allItems.map(item => item.json).filter(s => s && (s.nomPrenom || s.id));
  }
}

// Normaliser une chaîne pour comparaison insensible aux accents/casse
function normaliser(str) {
  if (!str) return '';
  return str
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toUpperCase()
    .replace(/[^A-Z0-9_]/g, '');
}

// Construire un index normalisé des salariés pour le matching rapide
const indexSalaries = {};
for (const s of salaries) {
  if (s.nomPrenom) {
    indexSalaries[normaliser(s.nomPrenom)] = s;
  }
}

const resultatsMatching = [];
const nonTrouves = [];
const emailsManquants = [];

for (const page of pages) {
  const nomPrenomBrut = page.nomPrenom || '';
  const nomPrenomNorm = normaliser(nomPrenomBrut);

  // Chercher d'abord par correspondance exacte normalisée
  let salarie = indexSalaries[nomPrenomNorm] || null;

  // Si pas trouvé, essayer une correspondance partielle (préfixe NOM)
  if (!salarie && nomPrenomNorm.length > 2) {
    const nomSeul = nomPrenomNorm.split('_')[0];
    if (nomSeul) {
      for (const [key, val] of Object.entries(indexSalaries)) {
        if (key.startsWith(nomSeul + '_') || key === nomSeul) {
          salarie = val;
          break;
        }
      }
    }
  }

  // Page individuelle découpée par le navigateur (pdf-lib)
  const pageBase64 = pagesBase64[page.pageIndex] || null;

  if (!salarie) {
    nonTrouves.push(nomPrenomBrut || 'Page ' + page.pageIndex);
    resultatsMatching.push({
      ...page,
      pageBase64,
      statut: 'NON_TROUVE',
      email: null,
      inclure: false
    });
  } else if (!salarie.email) {
    emailsManquants.push(salarie.nomPrenom);
    resultatsMatching.push({
      ...page,
      pageBase64,
      nomPrenom: salarie.nomPrenom,
      statut: 'EMAIL_MANQUANT',
      email: null,
      idDossierDrive: salarie.idDossierDrive,
      inclure: true
    });
  } else {
    resultatsMatching.push({
      ...page,
      pageBase64,
      nomPrenom: salarie.nomPrenom,
      statut: 'OK',
      email: salarie.email,
      idDossierDrive: salarie.idDossierDrive,
      inclure: true
    });
  }
}

return [{
  json: {
    mapping: resultatsMatching,
    nonTrouves,
    emailsManquants,
    nbTotal: resultatsMatching.length,
    nbOk: resultatsMatching.filter(m => m.statut === 'OK').length,
    nbProblemes: nonTrouves.length + emailsManquants.length,
    fileId,
    periode
  }
}];
